using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Foundation;

internal sealed class SingleLabelNormalBodyDocument : IScribeDocumentDefinition
{
    private const string Owner = "D5/S3/Quantum/Foundation/SingleLabelNormalBody.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Whole original positive annihilator bodies control every antipodal gap and force a native dimension bound at a singleton-label exclusion ball.",
        H("Single-label original normal bodies"), Blocks(
        Paragraph(Text("V is a finite dimensional real normed space, C is its original closed generating cone, and u is strictly positive on each nonzero cone vector. The normalized base K, all its extreme points P, and the full original interval of effects are retained. Every entire original exclusion D(p) has an injective affine chart of a closed Euclidean ball of positive dimension; the dimensions may vary, and segments are included. Only the chosen original p is required to have a singleton label fiber. No Pair, common dimension, width, projectivity, spectrality or Jordan structure is imposed.")),
        Describe.Lean(DescribeId.Create("singlelabel"), DeclarationHandle.Create(Owner + "SingleLabel"),
            H("Original singleton label fiber"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("Among all original pure states, equality of the entire exclusion set with D(p) forces equality with p."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("normalbody"), DeclarationHandle.Create(Owner + "normalBody"),
            H("Whole normalized positive annihilator body"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("This is the entire subset of the original continuous dual consisting of b nonnegative on the whole cone, with b(p)=0 and b(c)=1. Finite dimensionality identifies this dual with all original real-linear functionals."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("slope"), DeclarationHandle.Create(Owner + "slope"),
            H("Actual affine restriction slope"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("Compose the original functional with the linear part of the full ball chart and use the Euclidean Riesz identification. Thus b(a(z))=b(a(0))+inner(slope(b),z) for every chart vector z."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("slopebody"), DeclarationHandle.Create(Owner + "slopeBody"),
            H("Whole slope image"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("The image is taken over the entire normalized positive annihilator body, without selecting a finite effect menu or replacing its convex body."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("slope-formula"), DeclarationHandle.Create(Owner + "slope_formula"),
            H("Full affine slope formula"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("For every coordinate vector z, the original functional at a(z) equals its value at a(0) plus the inner product of its slope with z."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("chart-mem"), DeclarationHandle.Create(Owner + "chart_mem"),
            H("Entire ball membership"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("Every vector of norm at most one maps into the entire original exclusion D(p)."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("comparison-attained"), DeclarationHandle.Create(Owner + "comparison_attained"),
            H("An original confirming effect attains comparison"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("For every original base state x, compactness of the entire confirming-effect fiber supplies an original confirmer whose value at x is the comparison infimum."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("chart-unit-linear"), DeclarationHandle.Create(Owner + "chart_unit_linear"),
            H("Chart directions lie in the unit kernel"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("The original unit annihilates the chart's linear direction map on the whole coordinate space, because it is constant one on the affinely spanning closed unit ball."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("gap"), DeclarationHandle.Create(Owner + "gap"),
            H("Original antipodal all-effect gap"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("For any chart vector n, the gap is the original comparison at a(n),a(-n). Comparison is the infimum over every original proper effect confirming a(n). The theorem restricts n to unit vectors, so both endpoints are original pure states."))), DescribeRole.Definition),
        Describe.Lean(DescribeId.Create("single-label-neighbor"), DeclarationHandle.Create(Owner + "single_label_neighbor"),
            H("Local propagation of singleton labels"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("Assume only the original closed generating cone, strictly positive unit and entire positive-dimensional exclusion-ball charts. If p has a singleton label fiber, every pure q in D(p) also has a singleton label fiber. If another label shared D(q), two-point ball-face rigidity would collapse all pure boundary points of D(q) to p, contradicting its positive dimension. No global existence or topological premise is used."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("positive-annihilator-maximum"), DeclarationHandle.Create(Owner + "positive_annihilator_maximum"),
            H("Global maxima lie on the original exclusion face"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("Every nonzero positive functional b with b(p)=0 has a strictly positive global maximum at an original pure state in D(p). A compact exposed maximum face supplies a pure maximizer; its normalized functional confirms that maximizer and vanishes at p. Original zero symmetry then places the maximizer in D(p)."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("normal-body-bound"), DeclarationHandle.Create(Owner + "normal_body_bound"),
            H("Global bound by twice the original unit"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("For every member of the entire normalized body, positivity on the whole chart ball bounds its slope norm by one. The global maximum identity transfers the resulting bound of two from D(p) to the entire base and hence gives zero <= b <= 2u on the whole cone."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("normal-body-compact"), DeclarationHandle.Create(Owner + "normal_body_compact"),
            H("Compactness in the original dual"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("The whole normalized body is closed in the finite dimensional original dual. Its global bound places it inside the compact interval of all effects for the strictly positive unit 2u. No compactness of the pure-state carrier is assumed."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("slope-body-original"), DeclarationHandle.Create(Owner + "slope_body_original"),
            H("Exact original full-ball slope definition"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("Membership v in the whole image is equivalent to existence of an original real-linear b positive on C, annihilating p, normalized at a(0), with b(a(z))=1+inner(v,z) for every z of the whole closed unit ball. The full ball has full affine span, so the affine formula uniquely determines the restriction slope."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("slope-body-geometry"), DeclarationHandle.Create(Owner + "slope_body_geometry"),
            H("Compact convex whole slope body"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("The full slope map is linear and continuous, so the image of the compact convex original body is compact and convex. Its exact original affine formula and positivity on the whole unit ball give containment in the closed unit ball."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("positive-ray"), DeclarationHandle.Create(Owner + "positive_ray"),
            H("Actual positive slope on every unit ray"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("For every unit direction n, the actual boundary state q=a(n) has a singleton label by local propagation. A common original confirmer of q vanishing on all of D(q) has restriction 1-lambda+lambda inner(n,z) on D(p), with zero < lambda <= 1/2. A zero lambda would make all pure states of D(p) share D(q). Normalizing this actual confirmer at a(0) gives a member of the entire original body with slope t n, where zero < t <= 1."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("slope-body-inradius"), DeclarationHandle.Create(Owner + "slope_body_inradius"),
            H("Finite directional selection gives a uniform inner ball"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("Choose an actual positive ray point for each of the finitely many signed coordinate directions. Their positive minimum eta and convexity give all signed eta-axis points. Averaging d coordinate points proves containment of the Euclidean ball of radius eta/d, which is positive and at most one. This sufficient radius need not be optimal; the body remains the whole image."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("zero-gap-iff"), DeclarationHandle.Create(Owner + "zero_gap_iff"),
            H("Exact zero gap locus"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("For every original unit direction, the original all-effect gap vanishes exactly when that unit direction belongs to the whole slope body. A unit slope yields the legal original confirming effect b/2. Conversely compactness of the entire confirming-effect fiber gives an attained zero, hence the antipode belongs to D(q). A common original confirmer vanishes there and at p, and doubling it realizes the exact unit slope. This equivalence does not require the singleton-label hypothesis."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("uniform-original-gap"), DeclarationHandle.Create(Owner + "uniform_original_gap"),
            H("Uniform bound over all original unit directions"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("For each fixed singleton-label p and every full chart, one radius zero < rho <= 1 satisfies rho-ball containment. For every unit n the original gap is at most (1-rho)/(1+rho), which is strictly below one, and its zero locus is exactly membership of n in the whole slope body. A positive annihilator of slope rho n has global maximum 1+rho, so dividing by that value gives a legal effect in the entire original interval."))), DescribeRole.Theorem),
        Describe.Lean(DescribeId.Create("native-dimension"), DeclarationHandle.Create(Owner + "native_dimension"),
            H("Dimension bound in the original carrier"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text("For every original pure q in D(p) and its entire chart, dim(V) >= d(p)+d(q)+1. Positivity makes every functional annihilating p vanish on the actual d(q)-1 tangent directions of D(q) at p. These directions lie in ker(u), whereas u(p)=1. The inner slope ball separates the constant and all d(p) directions of D(p). Their direct sum with p and the actual tangent space injects into V, giving the bound by finite dimensional linear algebra."))), DescribeRole.Theorem),
        Paragraph(Text("The local theorem fixes a singleton-label p and proves neighbor propagation without importing a global existence theorem. In the case where every full ball has dimension three, its dimension inequality gives seven once such a p exists. Unconditional existence from EB alone requires the separate global topological theorem; that theorem is not supplied here. A positive inner radius does not assert that the body equals the unit ball or that every antipodal gap vanishes. These are mathematical statements about the specified original model, without a physical realization or literature-priority claim.")))));
}
